def factorial(n: int) -> int:
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def is_palindrome(word: str) -> bool:
    clean = word.lower()
    return clean == clean[::-1]

import math
def circle_area(radius: float) -> float:
    return math.pi * radius ** 2

